<script>
const video=document.getElementById('scanner-video'),canvas=document.getElementById('scanner-canvas'),overlay=document.getElementById('face-overlay'),toggle=document.getElementById('scan-toggle'),controls=document.getElementById('scanner-controls'),actionLabel=document.getElementById('scanner-action-label'),status=document.getElementById('scanner-status'),requestedCamera=<?= json_encode($requestedCamera) ?>,csrfToken=<?= json_encode($_SESSION['csrf_token']) ?>;
let stream=null,timer=null,running=false,scanType=null,hideTimer=null,manualStudent=null,searchTimer=null,visitorTimer=null,visitorPollTimer=null,visitorCursor=Number(sessionStorage.getItem('scanner-visitor-cursor')||0);
const recentlyShown=new Map(),unknownTracks=[],previewTracks=[];
const visitorStorageKey='scanner-visitor-queue';
const visitorQueue=(()=>{try{const saved=JSON.parse(sessionStorage.getItem(visitorStorageKey)||'[]');return Array.isArray(saved)?saved.filter(item=>item?.image_path&&Number.isFinite(item.ready_at)):[]}catch(error){return[]}})();
function setStatus(message){status.textContent=message}
function showControls(){controls.classList.remove('scanner-controls-hidden');clearTimeout(hideTimer);hideTimer=setTimeout(()=>controls.classList.add('scanner-controls-hidden'),3000)}
function renderToggle(){toggle.className='inline-flex items-center gap-2 rounded-xl px-4 py-3 font-bold text-white '+(running?'bg-red-600 hover:bg-red-700':'bg-blue-600 hover:bg-blue-700');toggle.innerHTML=running?'<span aria-hidden="true">■</span> Stop scanner':'<span aria-hidden="true">▶</span> Start scanner'}
function setActionLabel(type){if(!type){actionLabel.classList.add('hidden');actionLabel.textContent='';return}const automatic=type==='auto';actionLabel.textContent=automatic?'Automatic time in / time out':'Recording '+type.replace('_',' ');actionLabel.className='absolute bottom-20 left-5 rounded-xl bg-black/45 px-4 py-2 text-xs font-bold uppercase tracking-widest backdrop-blur '+(automatic?'text-blue-200':(type==='time_out'?'text-amber-200':'text-emerald-200'))}
function stop(){running=false;scanType=null;clearTimeout(timer);if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}video.srcObject=null;overlay.getContext('2d').clearRect(0,0,overlay.width,overlay.height);setActionLabel(null);setStatus('Scanner stopped. Choose Start scanner to use a camera.');renderToggle()}
function cameraError(error){if(error?.name==='NotAllowedError')return 'Camera permission was blocked. Allow camera access in the browser, then try again.';if(error?.name==='NotFoundError')return 'No camera was found. Connect the camera, then reload this page.';if(error?.name==='NotReadableError')return 'The camera is being used by another app. Close Teams, Zoom, Camera, or another scanner and try again.';return 'The selected camera could not start. Choose the camera again from the dashboard and retry.'}
async function isEmeetCamera(deviceId){if(!deviceId)return false;try{const device=(await navigator.mediaDevices.enumerateDevices()).find(item=>item.kind==='videoinput'&&item.deviceId===deviceId);return /emeet|c60|usb video/i.test(device?.label||'')}catch(error){return false}}
async function openCamera(deviceId,highDefinition=false){const resolution=highDefinition?{width:{ideal:1920,max:1920},height:{ideal:1080,max:1080}}:{width:{ideal:960,max:1280},height:{ideal:540,max:720}};return navigator.mediaDevices.getUserMedia({video:{...(deviceId?{deviceId:{exact:deviceId}}:{}),...resolution,frameRate:{ideal:30,max:30}},audio:false})}
async function optimizeCamera(){const track=stream?.getVideoTracks()[0],capabilities=track?.getCapabilities?.();if(!track||!capabilities)return;const settings={};if(capabilities.focusMode?.includes('continuous'))settings.focusMode='continuous';if(capabilities.exposureMode?.includes('continuous'))settings.exposureMode='continuous';if(capabilities.whiteBalanceMode?.includes('continuous'))settings.whiteBalanceMode='continuous';if(Object.keys(settings).length)try{await track.applyConstraints({advanced:[settings]})}catch(error){console.debug('Camera does not support automatic focus settings.',error)}}
async function start(type){stop();setStatus('Opening camera…');try{const deviceId=requestedCamera||localStorage.getItem('attendance-camera')||'',highDefinition=await isEmeetCamera(deviceId);try{stream=await openCamera(deviceId,highDefinition)}catch(error){if(!deviceId||!['OverconstrainedError','NotFoundError'].includes(error?.name))throw error;localStorage.removeItem('attendance-camera');setStatus('The previous camera is no longer available; opening the default camera…');stream=await openCamera('')}await optimizeCamera();video.srcObject=stream;await video.play();if(!video.videoWidth||!video.videoHeight)throw new Error('Camera did not provide video frames.');scanType=type;running=true;setActionLabel(type);const settings=stream.getVideoTracks()[0]?.getSettings?.()||{};setStatus('Camera is live'+(settings.width&&settings.height?' ('+settings.width+'x'+settings.height+')':'')+'. Keep all faces visible; they are checked together.');renderToggle();scan()}catch(error){console.error('Unable to open the selected camera.',error);stop();setStatus(cameraError(error),'error')}}
function drawFaces(faces){const width=video.clientWidth,height=video.clientHeight,ctx=overlay.getContext('2d');overlay.width=width;overlay.height=height;ctx.clearRect(0,0,width,height);if(!faces?.length||!video.videoWidth)return;const scale=Math.max(width/video.videoWidth,height/video.videoHeight),offsetX=(width-video.videoWidth*scale)/2,offsetY=(height-video.videoHeight*scale)/2;ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.shadowColor='rgba(0,0,0,.75)';ctx.shadowBlur=5;faces.forEach(face=>{const box=face.box;if(!box)return;const x=box.left/canvas.width*video.videoWidth*scale+offsetX,y=box.top/canvas.height*video.videoHeight*scale+offsetY,w=(box.right-box.left)/canvas.width*video.videoWidth*scale,h=(box.bottom-box.top)/canvas.height*video.videoHeight*scale,corner=Math.min(26,w/3,h/3);ctx.beginPath();ctx.moveTo(x+corner,y);ctx.lineTo(x,y);ctx.lineTo(x,y+corner);ctx.moveTo(x+w-corner,y);ctx.lineTo(x+w,y);ctx.lineTo(x+w,y+corner);ctx.moveTo(x,y+h-corner);ctx.lineTo(x,y+h);ctx.lineTo(x+corner,y+h);ctx.moveTo(x+w-corner,y+h);ctx.lineTo(x+w,y+h);ctx.lineTo(x+w,y+h-corner);ctx.stroke()});ctx.shadowBlur=0}
function previewFaces(faces){const now=Date.now();for(let index=previewTracks.length-1;index>=0;index--)if(now-previewTracks[index].lastSeen>1100)previewTracks.splice(index,1);(faces||[]).forEach(face=>{const box=face.box;if(!box)return;let track=previewTracks.find(item=>overlap(item.box,box)>=.45);if(!track){previewTracks.push({box,lastSeen:now,hits:1});return}track.box=box;track.lastSeen=now;track.hits++});drawFaces(previewTracks.filter(track=>track.hits>=2).map(track=>({box:track.box})))}
function showMatches(matches){const stack=document.getElementById('detected-stack'),now=Date.now();matches.forEach(match=>{const student=match.student||{},id=String(student.STUDENT_ID||''),state=match.action||scanType||'time_in',last=recentlyShown.get(id);if(!id||(last&&last.state===state&&last.until>now))return;recentlyShown.set(id,{state,until:now+5000});const card=document.createElement('div');card.className='flex w-72 translate-y-2 items-center gap-3 rounded-2xl bg-black/75 p-3 text-left text-white opacity-0 shadow-2xl ring-1 ring-white/20 backdrop-blur transition-all duration-500';const image=document.createElement('img');image.className='h-12 w-12 rounded-xl object-cover';image.src='../'+(student.IMAGE_PATH||'image/student-preview.png');image.alt='';const text=document.createElement('div');text.innerHTML='<p class="text-xs font-bold uppercase tracking-widest text-blue-200"></p><p class="mt-1 text-base font-black"></p><p class="mt-0.5 text-xs text-slate-200"></p>';text.querySelector('p:first-child').textContent=match.manual?'Manual attendance':(match.action==='time_out'?'Time out face detected':(match.action==='complete'?'Attendance already complete':'Time in face detected'));text.querySelector('p:nth-child(2)').textContent=student.STUDENT_NAME||'Student';text.querySelector('p:nth-child(3)').textContent=match.message||(match.logged?'Attendance recorded':'Already recorded');card.append(image,text);stack.appendChild(card);requestAnimationFrame(()=>card.classList.remove('translate-y-2','opacity-0'));setTimeout(()=>card.classList.add('translate-y-2','opacity-0'),4000);setTimeout(()=>card.remove(),4600)})}
function overlap(a,b){const left=Math.max(a.left,b.left),top=Math.max(a.top,b.top),right=Math.min(a.right,b.right),bottom=Math.min(a.bottom,b.bottom),intersection=Math.max(0,right-left)*Math.max(0,bottom-top),areaA=Math.max(1,(a.right-a.left)*(a.bottom-a.top)),areaB=Math.max(1,(b.right-b.left)*(b.bottom-b.top));return intersection/(areaA+areaB-intersection)}
function saveVisitorQueue(){try{sessionStorage.setItem(visitorStorageKey,JSON.stringify(visitorQueue))}catch(error){console.debug('Could not persist visitor alert queue.',error)}}
function scheduleVisitorAlert(){clearTimeout(visitorTimer);visitorTimer=null;if(!visitorQueue.length)return;const readyAt=Math.min(...visitorQueue.map(entry=>entry.ready_at));visitorTimer=setTimeout(showVisitorAlert,Math.max(0,readyAt-Date.now()))}
function queueVisitor(entry){if(!entry?.image_path||visitorQueue.some(item=>item.entry_id===entry.entry_id))return;visitorCursor=Math.max(visitorCursor,Number(entry.entry_id)||0);sessionStorage.setItem('scanner-visitor-cursor',String(visitorCursor));const detectedAt=Number(entry.detected_at_ms)||Date.now();visitorQueue.push({...entry,ready_at:detectedAt+30000});saveVisitorQueue();scheduleVisitorAlert()}
function showVisitorAlert(){visitorTimer=null;const now=Date.now(),entries=visitorQueue.filter(entry=>entry.ready_at<=now);if(!entries.length){scheduleVisitorAlert();return}for(let index=visitorQueue.length-1;index>=0;index--)if(visitorQueue[index].ready_at<=now)visitorQueue.splice(index,1);saveVisitorQueue();scheduleVisitorAlert();const images=document.getElementById('visitor-images'),modal=document.getElementById('visitor-modal');images.replaceChildren();document.getElementById('visitor-title').textContent=entries.length+' visitor or unregistered student'+(entries.length===1?'':'s')+' detected';entries.forEach((entry,index)=>{const figure=document.createElement('figure');figure.className='overflow-hidden rounded-xl bg-slate-100';const image=document.createElement('img');image.className='aspect-square w-full object-cover';image.src='../'+entry.image_path;image.alt='Unregistered visitor '+(index+1);figure.appendChild(image);images.appendChild(figure)});modal.classList.replace('hidden','flex')}
function removeVisitorEntry(entryId){if(!entryId)return;for(let index=visitorQueue.length-1;index>=0;index--)if(visitorQueue[index].entry_id===entryId)visitorQueue.splice(index,1);saveVisitorQueue();scheduleVisitorAlert();const form=new FormData();form.append('csrf_token',csrfToken);form.append('entry_id',entryId);fetch('remove-unregistered.php',{method:'POST',body:form}).catch(error=>console.debug('Could not remove superseded visitor capture.',error))}
function cancelRegisteredVisitorTracks(matches){(matches||[]).forEach(match=>{const box=match.box;if(!box)return;unknownTracks.forEach(track=>{if(overlap(track.box,box)>=.35){track.confirmed=true;if(track.entryId)removeVisitorEntry(track.entryId)}})})}
async function saveUnknownFace(box,frame,track){const form=new FormData();form.append('csrf_token',csrfToken);form.append('frame',frame);form.append('box',JSON.stringify(box));try{const response=await fetch('log-unregistered.php',{method:'POST',body:form});const result=await response.json();if(result.saved){track.entryId=result.entry_id;if(track.confirmed)removeVisitorEntry(track.entryId);else queueVisitor(result)}else setStatus(result.message||'Could not save the unregistered face snapshot.')}catch(error){console.error('Could not save unregistered face.',error);setStatus('Could not save the unregistered face snapshot.')}}
scheduleVisitorAlert();
async function pollVisitorAlerts(){try{const response=await fetch('visitor-alerts.php?after_id='+encodeURIComponent(visitorCursor));const data=await response.json();(data.entries||[]).forEach(queueVisitor);visitorCursor=Math.max(visitorCursor,Number(data.latest_id)||0);sessionStorage.setItem('scanner-visitor-cursor',String(visitorCursor))}catch(error){console.debug('Could not check saved visitor alerts.',error)}finally{visitorPollTimer=setTimeout(pollVisitorAlerts,5000)}}
pollVisitorAlerts();
function handleUnknownFaces(faces,frame){const now=Date.now();for(let index=unknownTracks.length-1;index>=0;index--)if(now-unknownTracks[index].lastSeen>5000)unknownTracks.splice(index,1);faces.forEach(face=>{const box=face.box;if(!box)return;let track=unknownTracks.find(item=>overlap(item.box,box)>=.35);if(!track){unknownTracks.push({box,lastSeen:now,firstSeen:now,hits:1,saved:false,confirmed:false,entryId:null});return}track.box=box;track.lastSeen=now;track.hits++;if(!track.saved&&!track.confirmed&&track.hits>=4&&now-track.firstSeen>=2500){track.saved=true;setStatus('Unregistered face detected — saving snapshot…');saveUnknownFace(box,frame,track)}})}
function cameraFrameBlob(){return new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.58))}
async function scan(){if(!running||!stream||video.readyState<2||!video.videoWidth)return;const scale=Math.min(1,640/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d',{alpha:false}).drawImage(video,0,0,canvas.width,canvas.height);try{const frame=await cameraFrameBlob();if(!frame)throw new Error('Could not encode camera frame.');const form=new FormData();form.append('frame',frame,'scanner-frame.jpg');form.append('scan_type',scanType);const response=await fetch('scan-match.php',{method:'POST',body:form});if(!response.ok)throw new Error('Recognition request failed ('+response.status+').');const result=await response.json(),unregistered=result.unregistered||[];previewFaces(result.preview_faces||result.faces||[]);cancelRegisteredVisitorTracks(result.recognized_faces||result.matches);if(unregistered.length)handleUnknownFaces(unregistered,canvas.toDataURL('image/jpeg',.78));if(result.matches?.length){setStatus('Face recognized. Attendance checked.','success');showMatches(result.matches)}else if(unregistered.length)setStatus('Face detected. Keeping it in view to save an unregistered snapshot…');else if(result.message==='Face detected. Confirming identity…')setStatus(result.message);else if(result.message&&result.message!=='No face detected.')setStatus(result.message,'error')}catch(error){console.error('Recognition service unavailable.',error);setStatus('Recognition could not process this frame. Keep the scanner open and try again.','error')}finally{if(running)timer=setTimeout(scan,20)}}
async function selectStudent(id){const message=document.getElementById('manual-message'),result=document.getElementById('manual-result'),options=document.getElementById('manual-options');options.classList.add('hidden');message.textContent='Loading student…';result.classList.add('hidden');const response=await fetch('manual-student.php?id='+encodeURIComponent(id));const data=await response.json();if(!data.student){manualStudent=null;message.textContent=data.message||'Student not found.';return}manualStudent=data.student;document.getElementById('manual-image').src='../'+(manualStudent.IMAGE_PATH||'image/student-preview.png');document.getElementById('manual-name').textContent=manualStudent.STUDENT_NAME;document.getElementById('manual-id-label').textContent=manualStudent.STUDENT_ID;const timeInButton=document.getElementById('mark-present'),timeOutButton=document.getElementById('mark-time-out');timeInButton.textContent=data.has_time_in?'Time in already recorded':'Record time in';timeInButton.disabled=data.has_time_in;timeInButton.className='rounded-xl px-4 py-3 font-bold text-white '+(data.has_time_in?'bg-slate-400':'bg-emerald-600 hover:bg-emerald-700');timeOutButton.textContent=data.has_time_out?'Time out already recorded':(data.has_time_in?'Record time out':'Time out requires time in');timeOutButton.disabled=!data.has_time_in||data.has_time_out;timeOutButton.className='rounded-xl px-4 py-3 font-bold text-white '+(timeOutButton.disabled?'bg-slate-400':'bg-amber-500 hover:bg-amber-600');message.textContent='';result.classList.remove('hidden')}
function searchStudents(){const name=document.getElementById('manual-student-name').value.trim(),options=document.getElementById('manual-options');clearTimeout(searchTimer);if(name.length<2){options.classList.add('hidden');return}searchTimer=setTimeout(async()=>{const response=await fetch('manual-students-search.php?q='+encodeURIComponent(name));const data=await response.json();options.innerHTML='';(data.students||[]).forEach(student=>{const button=document.createElement('button');button.type='button';button.className='flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-slate-100';button.textContent=student.STUDENT_NAME+' · '+student.STUDENT_ID;button.onclick=()=>{document.getElementById('manual-student-name').value=student.STUDENT_NAME;selectStudent(student.STUDENT_ID)};options.appendChild(button)});options.classList.toggle('hidden',!options.children.length)},250)}
async function saveManualAttendance(type){if(!manualStudent)return;const form=new FormData();form.append('student_id',manualStudent.STUDENT_ID);form.append('scan_type',type);form.append('csrf_token',csrfToken);const response=await fetch('manual-attendance-save.php',{method:'POST',body:form});const data=await response.json();if(data.student){document.getElementById('manual-modal').classList.replace('flex','hidden');showMatches([{student:data.student,logged:data.logged,action:data.action,message:data.message,manual:true}])}else document.getElementById('manual-message').textContent=data.message||'Could not record attendance.'}
toggle.onclick=()=>running?stop():start('auto');
document.getElementById('close-visitor-modal').onclick=()=>document.getElementById('visitor-modal').classList.replace('flex','hidden');document.getElementById('continue-scanning').onclick=()=>document.getElementById('visitor-modal').classList.replace('flex','hidden');
document.getElementById('manual-attendance').onclick=()=>{document.getElementById('manual-modal').classList.replace('hidden','flex');setTimeout(()=>document.getElementById('manual-student-name').focus(),0);showControls()};
document.getElementById('close-manual').onclick=()=>document.getElementById('manual-modal').classList.replace('flex','hidden');document.getElementById('manual-student-name').oninput=searchStudents;document.getElementById('mark-present').onclick=()=>saveManualAttendance('time_in');document.getElementById('mark-time-out').onclick=()=>saveManualAttendance('time_out');
document.getElementById('back-button').onclick=()=>{document.getElementById('exit-modal').classList.replace('hidden','flex');setTimeout(()=>document.getElementById('exit-password').focus(),0)};document.getElementById('cancel-exit').onclick=()=>document.getElementById('exit-modal').classList.replace('flex','hidden');
document.addEventListener('mousemove',showControls);document.addEventListener('touchstart',showControls,{passive:true});window.addEventListener('beforeunload',stop);renderToggle();showControls();
</script>
<script src="manual-attendance.js"></script>
</body></html>
